"""
Matrix and Vector Library without numpy

Provides basic linear algebra operations including addition, multiplication,
transposition, determinant calculation, inverse by Gauss-Jordan elimination, and
solving linear systems with input validation.
"""
from typing import List, Union

Matrix = List[List[float]]
Vector = List[float]


def validate_matrix(matrix: Matrix) -> None:
    """Validate if the input is a proper matrix."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("Matrix must be a non-empty list of lists")
    row_length = len(matrix[0])
    if row_length == 0:
        raise ValueError("Matrix rows must be non-empty")
    for row in matrix:
        if not isinstance(row, list) or len(row) != row_length:
            raise ValueError("All rows must be lists of the same length")
        for item in row:
            if not isinstance(item, (int, float)):
                raise ValueError("Matrix elements must be numbers")


def validate_vector(vector: Vector) -> None:
    """Validate if the input is a proper vector."""
    if not isinstance(vector, list) or not vector:
        raise ValueError("Vector must be a non-empty list")
    for item in vector:
        if not isinstance(item, (int, float)):
            raise ValueError("Vector elements must be numbers")


def add_matrices(A: Matrix, B: Matrix) -> Matrix:
    """Add two matrices."""
    validate_matrix(A)
    validate_matrix(B)
    if len(A) != len(B) or len(A[0]) != len(B[0]):
        raise ValueError("Matrices must have the same dimensions")
    return [[A[i][j] + B[i][j] for j in range(len(A[0]))] for i in range(len(A))]


def multiply_matrices(A: Matrix, B: Matrix) -> Matrix:
    """Multiply two matrices."""
    validate_matrix(A)
    validate_matrix(B)
    if len(A[0]) != len(B):
        raise ValueError("Number of columns of A must equal number of rows of B")
    result = []
    for i in range(len(A)):
        row = []
        for j in range(len(B[0])):
            element = 0
            for k in range(len(B)):
                element += A[i][k] * B[k][j]
            row.append(element)
        result.append(row)
    return result


def transpose_matrix(matrix: Matrix) -> Matrix:
    """Transpose a matrix."""
    validate_matrix(matrix)
    return [[matrix[j][i] for j in range(len(matrix))] for i in range(len(matrix[0]))]


def matrix_minor(matrix: Matrix, i: int, j: int) -> Matrix:
    """Return minor of matrix excluding i-th row and j-th column."""
    return [row[:j] + row[j+1:] for idx,row in enumerate(matrix) if idx != i]


def determinant(matrix: Matrix) -> float:
    """Calculate determinant recursively."""
    validate_matrix(matrix)
    if len(matrix) != len(matrix[0]):
        raise ValueError("Matrix must be square to calculate determinant")
    n = len(matrix)
    if n == 1:
        return matrix[0][0]
    if n == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    det = 0
    for c in range(n):
        det += ((-1)**c) * matrix[0][c] * determinant(matrix_minor(matrix, 0, c))
    return det


def gauss_jordan_inverse(matrix: Matrix) -> Matrix:
    """Calculate inverse of a matrix using Gauss-Jordan elimination."""
    validate_matrix(matrix)
    n = len(matrix)
    if n != len(matrix[0]):
        raise ValueError("Matrix must be square to invert")
    det = determinant(matrix)
    if det == 0:
        raise ValueError("Matrix is singular and cannot be inverted")

    # Create augmented matrix with identity
    augmented = [row[:] + [float(i == j) for j in range(n)] for i,row in enumerate(matrix)]

    # Forward elimination
    for i in range(n):
        pivot = augmented[i][i]
        if abs(pivot) < 1e-15:
            # Find row to swap
            for r in range(i+1, n):
                if abs(augmented[r][i]) > 1e-15:
                    augmented[i], augmented[r] = augmented[r], augmented[i]
                    pivot = augmented[i][i]
                    break
            else:
                raise ValueError("Matrix is singular and cannot be inverted")

        # Normalize pivot row
        for j in range(i*2, 2*n):
            augmented[i][j] /= pivot

        # Eliminate other rows
        for r in range(n):
            if r != i:
                factor = augmented[r][i]
                for c in range(i*2, 2*n):
                    augmented[r][c] -= factor * augmented[i][c]

    inverse = [row[n:] for row in augmented]
    return inverse


def solve_linear_system(A: Matrix, b: Vector) -> Vector:
    """Solve linear system Ax = b using Gauss-Jordan elimination."""
    validate_matrix(A)
    validate_vector(b)
    n = len(A)
    if len(A[0]) != n:
        raise ValueError("Matrix A must be square")
    if len(b) != n:
        raise ValueError("Vector b length must match matrix A size")

    # Create augmented matrix
    augmented = [A[i][:] + [b[i]] for i in range(n)]

    for i in range(n):
        # Pivot element
        max_row = i
        for r in range(i+1, n):
            if abs(augmented[r][i]) > abs(augmented[max_row][i]):
                max_row = r
        if abs(augmented[max_row][i]) < 1e-15:
            raise ValueError("System has no unique solution")
        # Swap
        augmented[i], augmented[max_row] = augmented[max_row], augmented[i]

        pivot = augmented[i][i]
        for c in range(i, n+1):
            augmented[i][c] /= pivot

        for r in range(n):
            if r != i:
                factor = augmented[r][i]
                for c in range(i, n+1):
                    augmented[r][c] -= factor * augmented[i][c]

    return [augmented[i][n] for i in range(n)]


if __name__ == "__main__":
    # Simple tests
    A = [[4,7],[2,6]]
    B = [[3,8],[5,1]]
    print("A + B =", add_matrices(A,B))
    print("A * B =", multiply_matrices(A,B))
    print("Transpose A =", transpose_matrix(A))
    print("Determinant A =", determinant(A))
    print("Inverse A =", gauss_jordan_inverse(A))
    print("Solve A x = b, with b=[1,1]", solve_linear_system(A,[1,1]))
